#!/bin/sh
# Runs ONCE, on an empty data directory, as the postgres OS user (official image init hook).
# Creates the run-time role plotinium_app with the password generated by ops/db/entrypoint.sh.
# Roles are cluster-wide, so migrations only GRANT to this role (database.md §3.2, §4.1).
set -eu

pw=$(cat /run/plotinium/app_password)
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" -v pw="$pw" <<'SQL'
-- The role owns nothing; PostgreSQL 18 grants no CREATE on schema public to PUBLIC, so it cannot
-- run DDL there (database.md §3.2, test 'DB-04 the app role gets 42501 ... DDL').
CREATE ROLE plotinium_app LOGIN PASSWORD :'pw';
SQL
